class Solution { public String longestNiceSubstring(String text){if(text.length()<2)return "";Set<Character> set=new HashSet<>();for(char letter:text.toCharArray())set.add(letter);for(int i=0;i<text.length();i++){char letter=text.charAt(i);if(!set.contains(Character.toLowerCase(letter))||!set.contains(Character.toUpperCase(letter))){String left=longestNiceSubstring(text.substring(0,i)),right=longestNiceSubstring(text.substring(i+1));return left.length()>=right.length()?left:right;}}return text;} }
